package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.ConvergenceChecker;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.FunctionEvaluationException;
import org.apache.commons.math3.optim.univariate.GoalType;
import org.apache.commons.math3.optim.univariate.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.UnivariateRealPointValuePair;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for MultiStartUnivariateRealOptimizer.optimize(FUNC, GoalType, double, double)
 */
public class MultiStartUnivariateRealOptimizer_optimize_TriageGen0Test {

    private BaseUnivariateRealOptimizer<UnivariateRealFunction> mockOptimizer;
    private MultiStartUnivariateRealOptimizer optimizer;
    private UnivariateRealFunction function;

    @Before
    public void setUp() {
        mockOptimizer = mock(BaseUnivariateRealOptimizer.class);
        // Using a real RandomGenerator for stability in setup, or mock if needed
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 3, new JDKRandomGenerator());
        function = x -> x * x; // f(x) = x^2
    }

    @Test
    public void testOptimize_MinimizationSuccess() throws FunctionEvaluationException {
        // Arrange
        double min = -10.0;
        double max = 10.0;
        double expectedStartValue = min + 0.5 / (max - min);

        UnivariateRealPointValuePair expectedResult = new AbstractUnivariateRealPointValuePair(0.0, 0.0);

        // The optimize(f, goal, min, max) calls optimize(f, goal, min, max, startValue)
        when(mockOptimizer.optimize(any(UnivariateRealFunction.class), any(GoalType.class), any(double.class), any(double.class), any(double.class)))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(function, GoalType.MINIMIZE, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(0.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);
    }

    @Test
    public void testOptimize_MaximizationSuccess() throws FunctionEvaluationException {
        // Arrange
        double min = 0.0;
        double max = 1.0;

        UnivariateRealPointValuePair expectedResult = new AbstractUnivariateRealPointValuePair(1.0, 1.0);

        when(mockOptimizer.optimize(any(UnivariateRealFunction.class), any(GoalType.class), any(double.class), any(double.class), any(double.class)))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(function, GoalType.MAXIMIZE, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(1.0, result.getPoint(), 1e-10);
        assertEquals(1.0, result.getValue(), 1e-10);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testOptimize_ThrowsFunctionEvaluationException() throws FunctionEvaluationException {
        // Arrange
        double min = -1.0;
        double max = 1.0;

        when(mockOptimizer.optimize(any(UnivariateRealFunction.class), any(GoalType.class), any(double.class), any(double.class), any(double.class)))
            .thenThrow(new FunctionEvaluationException(new RuntimeException("Eval error")));

        // Act
        optimizer.optimize(function, GoalType.MINIMIZE, min, max);
    }

    /**
     * Helper class to instantiate UnivariateRealPointValuePair for testing purposes
     * since it is an interface.
     */
    private static class AbstractUnivariateRealPointValuePair implements UnivariateRealPointValuePair {
        private final double point;
        private final double value;

        public AbstractUnivariateRealPointValuePair(double point, double value) {
            this.point = point;
            this.value = value;
        }

        @Override
        public double getPoint() { return point; }

        @Override
        public double getValue() { return value; }
    }
}
